// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz an arbitrary address as actor; the owner must be the deployer (set in constructor via msg.sender)
    // The general rule: when the true contract's NETM() is invoked by the owner, the owner's balance remains equal
    // to the initial distributed amount (i.e., non-zero and preserved). The mutant that zeroes balances breaks this.
    function testFuzz_property(address caller) public {
        // keep caller wide but non-zero to avoid trivial zero-address interactions
        vm.assume(caller != address(0));

        // The owner is the deployer (this contract ran new C() in setUp), owner == address(this test deployer) i.e., address(this)
        address owner = address(this);

        // Confirm initial owner balance equals totalDistributed via getter balanceOf
        uint256 beforeBal = c.balanceOf(owner);

        // owner must be able to call NETM(); simulate the call as the owner
        vm.prank(owner);
        // call NETM(); it's non-payable and onlyOwner
        c.NETM();

        // Read owner's balance after NETM
        uint256 afterBal = c.balanceOf(owner);

        // The general invariant: NETM() invoked by the owner does not decrease the owner's balance (reference preserves it);
        // mutant that clears balances will make afterBal == 0 while beforeBal > 0, violating this.
        assertTrue(afterBal >= beforeBal);
    }
}

