pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary address that may be any account; the property must hold for all addresses
    function testFuzz_property(address actor) public {
        // Keep domain wide: actor can be any address. We must ensure owner is msg.sender from deployment (set in C constructor)
        // The property: after owner calls NETM(), the balance of any address `actor` is equal to its pre-call balance
        // (i.e., NETM must not clear balances of arbitrary keys). The mutant that zeroes balances[owner] will violate
        // this for actor == owner (and potentially others) when owner's balance was non-zero.

        // Arrange: capture balance before calling NETM
        uint256 before = c.balanceOf(actor);

        // Act: call NETM as owner. The contract sets owner = msg.sender in constructor, so the deployer (this test contract)
        // is NOT the owner. We need to call as the owner. In the given contract, owner was set to msg.sender at deployment
        // time inside C's constructor; because we used `new C()` in setUp(), the test contract was the deployer and is owner.
        // So we call NETM as this contract (no vm.prank required).
        try c.NETM() {
            // succeeded
        } catch {
            // NETM is onlyOwner; on correct contract it won't revert when called by owner (this test contract)
        }

        // Assert: the balance of actor did not change by calling NETM()
        // This is a universal property for the reference; the mutant that zeroes balances[owner] will make it fail for actor==owner when before>0
        uint256 after = c.balanceOf(actor);
        assertTrue(after == before);
    }
}

