pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an arbitrary address 'who' and an arbitrary uint256 'amount'
    // We'll credit 'who' by using the contract's distribution mechanism (getTokens) so balances can vary,
    // then call NETM() as the owner and assert that the sum of all known balances still equals c.totalDistributed().
    // We only observe via public API: balanceOf and totalDistributed.
    function testFuzz_property(address who, uint256 times) public {
        // keep inputs wide but avoid trivial zero-times loop explosion
        uint256 t = bound(times, 0, 10);

        // Ensure we interact from distinct addresses: the contract deployer is owner (setUp), so owner operations use default msg.sender.
        // We will have several different addresses call getTokens to populate balances. Fuzzer chooses 'who' to be one of them.

        // Give some ether to the fuzzed participant so they can call getTokens
        vm.deal(who, 1 ether);

        // Have a few addresses call getTokens to create varied balances; include 'who' at least once when t>0
        for (uint i = 0; i < t; i++) {
            address participant = address(uint160(uint(keccak256(abi.encodePacked(who, i)))));
            vm.deal(participant, 1 ether);
            vm.prank(participant);
            // call getTokens payable with small value
            c.getTokens{value: 1 wei}();
        }

        // Record totalDistributed before NETM and compute the sum of balances of a sample of addresses including owner and 'who'.
        uint256 totalBefore = c.totalDistributed();

        // We'll sample a set of addresses to sum balances; include owner (deployer), the fuzzed 'who', and some pseudorandom addresses
        address ownerAddr = address(this); // not owner; owner is the deployer (this test contract deployed c via setUp), so owner is address(this) at deployment time
        // Actually owner in contract C was set to msg.sender at construction: setUp() used new C() from this test, so owner == address(this)
        ownerAddr = address(this);

        address[5] memory sampleAddrs;
        sampleAddrs[0] = ownerAddr;
        sampleAddrs[1] = who;
        for (uint i = 2; i < 5; i++) {
            sampleAddrs[i] = address(uint160(uint(keccak256(abi.encodePacked(who, i, block.timestamp)))));
        }

        // compute sum of sampled balances before
        uint256 sumBefore = 0;
        for (uint i = 0; i < sampleAddrs.length; i++) {
            sumBefore += c.balanceOf(sampleAddrs[i]);
        }

        // Call NETM() as owner
        vm.prank(ownerAddr);
        c.NETM();

        // compute totalDistributed after NETM and sum of sampled balances after
        uint256 totalAfter = c.totalDistributed();
        uint256 sumAfter = 0;
        for (uint i = 0; i < sampleAddrs.length; i++) {
            sumAfter += c.balanceOf(sampleAddrs[i]);
        }

        // The general rule: totalDistributed equals the sum of all balances. We cannot sum all addresses, but the change in totalDistributed must equal the change in the global sum of balances.
        // For our sampled set, if NETM altered balances unexpectedly (e.g., zeroing owner's balance), totalDistributed will remain unchanged in reference and the global sum of balances changes consistently.
        // We assert that totalDistributed did not decrease while the sampled sum decreased by more than total decreased — this detects the mutant which zeroes owner's balance but leaves totalDistributed unchanged.

        // Simpler one-statement invariant that the correct contract satisfies for all inputs: totalAfter == totalBefore.
        // The mutant does not change totalDistributed field in NETM, so totalAfter == totalBefore still holds for both. To catch mutant, assert that sumAfter >= sumBefore || totalAfter >= totalBefore
        // However that is not precise. Instead, assert that the difference (totalAfter - totalBefore) equals (sumAfter - sumBefore) for our sample when owner is among sampled addresses and owner had non-zero balance before.

        // We craft an assert that will hold for the correct contract for all inputs: if owner is in sample and owner's balance before > 0 then sumAfter == sumBefore.
        // The reference NETM preserves all balances (it sets balances[owner] = totalDistributed in constructor and NETM in reference sets owner balances to totalDistributed — actually NETM in reference sets balances[owner] = totalDistributed), so for any addresses that had balances before, NETM should not reduce them except for distribution logic which we didn't call. Therefore for our scenario sumAfter >= 0 and totalBefore == totalAfter.

        // To keep a single clear universal assertion that reference satisfies and mutant breaks: assert totalAfter == totalBefore && (sumAfter >= sumBefore);
        // The reference preserves totalDistributed and does not suddenly reduce sampled balances, so sumAfter >= sumBefore holds; the mutant that zeroes owner can make sumAfter < sumBefore while totalAfter unchanged.

        assertTrue(totalAfter == totalBefore && sumAfter >= sumBefore);
    }
}

