pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: addrOther is an arbitrary address (could be owner or any EOA)
    // We ensure addrOther != address(0) and pick initAmount > 0 to make its balance observable.
    function testFuzz_property(address addrOther, uint256 initAmount) public {
        // keep domain wide but sensible
        vm.assume(addrOther != address(0));
        initAmount = bound(initAmount, 1, 1e30);

        address owner = address(this); // deployer is owner by construction

        // Fund owner so it can initialize distributions if needed
        // Give owner the initial distributed balance by calling NETM once as owner (constructor set owner=msg.sender already)
        // Ensure addrOther has some balance before calling NETM by distributing to it via getTokens path.

        // Make addrOther eligible by ensuring it's not blacklisted initially
        // Call getTokens from addrOther to allocate some balance (value > 0 by default in contract)
        vm.deal(addrOther, 1 ether);
        vm.prank(addrOther);
        // call getTokens to receive tokens; if it reverts due to whitelist, this will revert — but by default blacklist is false
        c.getTokens{value: 0}(); // call with zero ether; getTokens uses value variable not msg.value, this simply triggers distribution of value

        uint256 before = c.balanceOf(addrOther);

        // Owner calls NETM()
        // owner is this contract (deployer), so call directly
        c.NETM();

        uint256 after = c.balanceOf(addrOther);

        // General rule: NETM should not clear the balance of an arbitrary non-zero address; i.e., after >= before
        // This holds for the reference contract for all inputs; the mutant that sets balances[owner]=0 can reduce balances and make after < before for some addrOther
        assertTrue(after >= before);
    }
}

