pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an address that will act as the owner and caller of NETM.
    // General rule: In the reference implementation, calling NETM() as the owner sets balances[owner] to totalDistributed (which is already the case at construction); it does not increment balances by a tiny nonzero delta. The mutant increments balances[owner] by 1, so for some owner inputs the post-call balance differs.
    function testFuzz_property(address ownerAddr) public {
        // Keep ownerAddr non-zero to be an admissible owner
        vm.assume(ownerAddr != address(0));

        // Ensure the contract's deployer (the test runner) is the initial owner stored in c.
        // The contract C sets owner = msg.sender at construction (setUp used new C()).
        // To exercise NETM as onlyOwner, we must call NETM from that owner. That owner is address(this) (the test contract) because setUp deployed c from this contract.
        // However, we still fuzz an arbitrary address to observe that calling NETM does not change balances of arbitrary accounts in the reference implementation.

        // Record balance of the fuzzed account before calling NETM
        uint256 before = c.balanceOf(ownerAddr);

        // Call NETM as the actual owner (the test contract) to trigger the code path.
        // NETM is onlyOwner, so we must call from the deployer (this test contract). We are already that.
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // Record balance after
        uint256 after = c.balanceOf(ownerAddr);

        // General universal property to assert: For any address (ownerAddr) and for a successful NETM call by the true owner, the balance of that arbitrary address must be unchanged in the reference implementation.
        // The mutant that increments balances[owner] by 1 will violate this when ownerAddr equals the owner address (the deployer), yielding after == before + 1.
        assertTrue(ok && after == before);
    }
}

