import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerAddr;

    function setUp() public { c = new C(); ownerAddr = address(uint160(address(this))); }

    function testFuzz_property() public {
        // The reference NETM() should set balances[owner] to totalDistributed (it assigns balances[owner] = totalDistributed in constructor-like NETM),
        // while the mutant increments it by 1. We call NETM() as the owner and assert balances(owner) == totalDistributed.

        // ensure this contract is the owner and call NETM()
        // call as this contract (the deployer is owner already), simply invoke NETM()
        c.NETM();

        // read totalDistributed and balanceOf(owner) via public getters
        uint256 td = c.totalDistributed();
        uint256 bal = c.balanceOf(address(this));

        // single assertion: in the correct contract balances(owner) equals totalDistributed.
        assertTrue(bal == td);
    }
}
